-- Carga inicial del álbum: únicamente los enlaces proporcionados. Respalde la base antes de ejecutar.
-- No vuelva a ejecutar este script: protege álbumes existentes contra sobrescritura.
SET XACT_ABORT ON;
BEGIN TRY
 BEGIN TRANSACTION;
 IF OBJECT_ID(N'dbo.HabitacionImagen', N'U') IS NOT NULL
   THROW 51200, 'HabitacionImagen ya existe; no se reemplazaran albumes existentes.', 1;
 CREATE TABLE dbo.HabitacionImagen (
  HabitacionImagenId int IDENTITY(1,1) NOT NULL CONSTRAINT PK_HabitacionImagen PRIMARY KEY,
  HabitacionId int NOT NULL,
  Url nvarchar(500) NOT NULL,
  Orden int NOT NULL CONSTRAINT CK_HabitacionImagen_Orden CHECK (Orden > 0),
  CONSTRAINT FK_HabitacionImagen_Habitacion FOREIGN KEY (HabitacionId) REFERENCES dbo.Habitacion(HabitacionId) ON DELETE CASCADE,
  CONSTRAINT UQ_HabitacionImagen_Orden UNIQUE (HabitacionId, Orden)
 );
 DECLARE @Fotos TABLE (SedeCodigo nvarchar(20), Numero nvarchar(10), Tipo nvarchar(100), Orden int, Url nvarchar(500));
 -- Esta consulta informa habitaciones que no coinciden con sede, número y tipo.
 SELECT DISTINCT f.SedeCodigo, f.Numero, f.Tipo AS TipoHabitacion FROM @Fotos f
 WHERE NOT EXISTS (SELECT 1 FROM dbo.Habitacion h JOIN dbo.Sede s ON s.SedeId=h.SedeId
   JOIN dbo.TipoHabitacion t ON t.TipoHabitacionId=h.TipoHabitacionId
   WHERE s.Codigo=f.SedeCodigo AND h.Numero=f.Numero AND t.Nombre=f.Tipo);
 SELECT h.HabitacionId, f.Url, f.Orden FROM @Fotos f
 JOIN dbo.Sede s ON s.Codigo=f.SedeCodigo
 JOIN dbo.Habitacion h ON h.SedeId=s.SedeId AND h.Numero=f.Numero
 JOIN dbo.TipoHabitacion t ON t.TipoHabitacionId=h.TipoHabitacionId AND t.Nombre=f.Tipo;
 -- Se eliminan las URL antiguas y se mantiene la imagen principal por compatibilidad.
 UPDATE h SET FotoUrl = (SELECT i.Url FROM dbo.HabitacionImagen i WHERE i.HabitacionId=h.HabitacionId AND i.Orden=1)
 FROM dbo.Habitacion h;
 SELECT COUNT(*) AS ImagenesCargadas, COUNT(DISTINCT HabitacionId) AS HabitacionesConImagenes FROM dbo.HabitacionImagen;
 COMMIT TRANSACTION;
END TRY
BEGIN CATCH
 IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
 THROW;
END CATCH;
